using ghidra.app.plugin.core.debug.service.tracermi;
using ghidra.app.script;
using ghidra.app.services;

public class ConnectTraceRmiScript : GhidraScript {

	TraceRmiService getService()
    {
		TraceRmiService service = state.getTool().getService(typeof(TraceRmiService));
		if (service != null) {
			return service;
		}
		state.getTool().addPlugin(typeof(TraceRmiPlugin).getName());
		return Objects.requireNonNull(state.getTool().getService(typeof(TraceRmiService)));
	}

	/* @Override */
	protected void run()
    {
		TraceRmiService service = getService();
		service.connect(new InetSocketAddress(askString("Trace RMI", "hostname", "localhost"),
			askInt("Trace RMI", "port")));
		println("Connected");

//		if (askYesNo("Execute?", "Execute 'echo test'?")) {
//			handler.getMethods().get("execute").invoke(Map.of("cmd", "script print('test')"));
//		}
	}
}
